  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
}

footer .container {
  text-align: center;
}

footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.9rem;
}

footer strong {
  color: var(--color-text);
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

.card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  padding: var(--spacing-lg);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card:hover {
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
  transform: translateY(-2px);
}

.card.featured {
  border: 2px solid var(--color-accent);
  box-shadow: 0 10px 30px rgba(14, 165, 233, 0.15);
  transform: scale(1.02);
}

.card.featured .badge {
  background-color: #0a79aa;
  color: var(--color-bg);
  display: inline-block;
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.price {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0;
}

.price-currency {
  font-size: 1.5rem;
  vertical-align: super;
}

.price-period {
  font-size: 1rem;
  color: var(--color-text-light);
  font-weight: 400;
}

.feature-list {
  list-style: none;
  margin: var(--spacing-lg) 0;
}

.feature-list li {
  padding: var(--spacing-sm) 0;
  padding-left: 1.75rem;
  position: relative;
  color: var(--color-text);
}

.feature-list li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
  font-size: 1.2rem;
}

.feature-list li.unavailable {
  color: var(--color-text-light);
  text-decoration: line-through;
}

.feature-list li.unavailable:before {
  content: "−";
  color: var(--color-border);
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--spacing-lg);
}

.comparison-table th,
.comparison-table td {
  padding: var(--spacing-md);
  text-align: left;
  border-bottom: 1px solid var(--color-border);
}

.comparison-table th {
  background-color: var(--color-bg-alt);
  font-weight: 600;
  color: var(--color-text);
}

.comparison-table tr:last-child th,
.comparison-table tr:last-child td {
  border-bottom: none;
}

.comparison-table tbody tr:hover {
  background-color: var(--color-bg-alt);
}

.comparison-table .feature-name {
  font-weight: 500;
  color: var(--color-text);
}

.comparison-table .check {
  color: var(--color-success);
  font-weight: bold;
  text-align: center;
}

.comparison-table .cross {
  color: var(--color-border);
  text-align: center;
}

.faq-item {
  margin-bottom: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 0.375rem;
  overflow: hidden;
}

.faq-question {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-md);
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 44px;
}

.faq-question:hover {
  background-color: var(--color-border);
}

.faq-question:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: -2px;
}

.faq-answer {
  padding: var(--spacing-md);
  color: var(--color-text-light);
  display: none;
}

.faq-item.open .faq-answer {
  display: block;
}

.faq-toggle {
  font-size: 1.5rem;
  transition: transform 0.2s ease;
}

.faq-item.open .faq-toggle {
  transform: rotate(180deg);
}

@media (min-width: 601px) {
  section {
    padding: var(--spacing-2xl) 0;
  }

  h1 {
    font-size: 3rem;
  }

  h2 {
    font-size: 2.25rem;
    margin-bottom: var(--spacing-xl);
  }

  .grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-lg);
  }

  .card.featured {
    grid-column: 2;
  }

  .comparison-table {
    font-size: 0.95rem;
  }

  .comparison-table th,
  .comparison-table td {
    padding: var(--spacing-lg);
  }
}

@media (max-width: 600px) {
  html {
    font-size: 15px;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  header {
    padding: var(--spacing-sm) 0;
  }

  .logo {
    font-size: 1.25rem;
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  h1 {
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
  }

  h2 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-md);
  }

  h3 {
    font-size: 1.1rem;
  }

  .grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .card.featured {
    grid-column: 1;
    transform: scale(1);
  }

  .price {
    font-size: 2rem;
  }

  .comparison-table {
    font-size: 0.85rem;
  }

  .comparison-table th,
  .comparison-table td {
    padding: var(--spacing-sm);
  }

  .faq-question {
    padding: var(--spacing-sm);
    font-size: 0.95rem;
  }

  .feature-list li {
    font-size: 0.95rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.pricing-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-accent) 100%);
  color: var(--color-bg);
  text-align: center;
  padding: var(--spacing-2xl) 0;
}

.pricing-hero h1 {
  color: var(--color-bg);
  margin-bottom: var(--spacing-md);
}

.pricing-hero-subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1.125rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-2xl);
}

.pricing-card {
  display: flex;
  flex-direction: column;
}

.pricing-card h3 {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

.pricing-description {
  font-size: 0.95rem;
  margin-bottom: var(--spacing-lg);
  color: var(--color-text-light);
  min-height: 2.5rem;
}

.pricing-card button {
  margin-bottom: var(--spacing-lg);
  width: 100%;
  justify-content: center;
}

.pricing-card .feature-list {
  flex-grow: 1;
}

.pricing-highlights {
  background-color: var(--color-bg-alt);
}

.pricing-highlights h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.pricing-universal {
  max-width: 600px;
  margin: 0 auto;
}

.pricing-table-wrapper {
  overflow-x: auto;
}

.faq-container {
  max-width: 700px;
  margin: 0 auto;
  margin-top: var(--spacing-2xl);
}

.faq-item {
  margin-bottom: var(--spacing-md);
}

.faq-question {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: 0.375rem;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 44px;
  color: var(--color-text);
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

.faq-question:hover {
  background-color: var(--color-border);
}

.faq-question:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: -2px;
  box-shadow: 0 0 0 2px var(--color-bg), 0 0 0 4px var(--color-accent);
}

.faq-answer {
  background-color: var(--color-bg);
  padding: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-top: none;
  border-radius: 0 0 0.375rem 0.375rem;
  color: var(--color-text-light);
  display: none;
}

.faq-item.open .faq-answer {
  display: block;
}

.faq-toggle {
  font-size: 0.75rem;
  transition: transform 0.2s ease;
  flex-shrink: 0;
  margin-left: var(--spacing-sm);
}

.faq-item.open .faq-toggle {
  transform: rotate(180deg);
}

.faq-answer p {
  margin-bottom: 0;
  color: var(--color-text-light);
}

@media (min-width: 601px) {
  .pricing-hero {
    padding: var(--spacing-2xl) 0;
  }

  .pricing-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: var(--spacing-lg);
  }

  .pricing-card.featured {
    transform: scale(1.02);
  }

  .pricing-universal {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: var(--spacing-lg);
    max-width: none;
  }

  .faq-container {
    max-width: 800px;
  }
}

@media (max-width: 600px) {
  .pricing-hero {
    padding: var(--spacing-xl) 0;
  }

  .pricing-hero h1 {
    font-size: 1.75rem;
  }

  .pricing-hero-subtitle {
    font-size: 1rem;
  }

  .pricing-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
    margin-top: var(--spacing-lg);
  }

  .pricing-card.featured {
    transform: scale(1);
  }

  .pricing-card h3 {
    font-size: 1.25rem;
  }

  .pricing-description {
    font-size: 0.9rem;
  }

  .pricing-universal {
    grid-template-columns: 1fr;
  }

  .pricing-universal li {
    font-size: 0.95rem;
  }

  .faq-container {
    max-width: 100%;
    margin-top: var(--spacing-lg);
  }

  .faq-question {
    padding: var(--spacing-sm);
    font-size: 0.95rem;
  }

  .faq-toggle {
    font-size: 0.7rem;
  }

  .faq-answer {
    padding: var(--spacing-sm);
    font-size: 0.9rem;
  }
}
